import json
from pathlib import Path

def transform_v3(grid):
    """Fill from source_row-1 to target_row-1 INCLUSIVE for each source"""
    H, W = len(grid), len(grid[0])
    result = [[0]*W for _ in range(H)]

    target_row = None
    all_4s = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 2:
                target_row = r
            if grid[r][c] == 4:
                all_4s.append((r, c))

    if target_row is None:
        return result

    for (source_r, source_c) in all_4s:
        source_col = source_c
        # Fill rows from source_row-1 to target_row-1 inclusive
        start_row = max(0, source_r - 1)
        end_row = min(H - 1, target_row - 1)
        for r in range(start_row, end_row):
            d = target_row - r - 1
            for col_delta in [source_col + d, source_col - d]:
                col = col_delta
                if 0 <= col < W:
                    result[r][col] = 4

    result[target_row] = [2]*W

    return result

