def transform_single_source(g):
    res = [[0]*W for _ in range(H)]

    sources = []
    target_row = None
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] == 4:
                sources.append((r, c))
            if g[r][c] == 2:
                target_row = r

    if not sources:
        return res

    best = min(sources, key=lambda s: abs(s[0] - target_row))
    sr, sc = best

